import shlex

class VariableMerger:
    @staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """
        Extend ``vars_dict`` with ``extra-vars``.

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars. Each element can be either:
                           - a dictionary with key-value pairs
                           - a string of the form "key=value" (may contain quoted values)
        :return: The updated dictionary (same reference as ``vars_dict``)
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dict")
        if not extra_vars:
            return vars_dict

        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, str):
                # Support shell-like parsing for quoted values
                try:
                    parts = shlex.split(item, comments=False)
                except ValueError:
                    parts = [item]
                for part in parts:
                    if '=' not in part:
                        continue
                    key, value = part.split('=', 1)
                    vars_dict[key] = value
            else:
                raise TypeError("Each element in extra_vars must be a dict or str")

        return vars_dict
